import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { getMeetings, updateMeetingStatus } from '../../api';

function HodDashboard({ user }) {
  const [meetings, setMeetings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [msg, setMsg] = useState('');

  useEffect(() => { load(); }, []);

  const load = async () => {
    try { const r = await getMeetings(); setMeetings(r.data); }
    catch (e) { console.error(e); }
    finally { setLoading(false); }
  };

  const flash = (m) => { setMsg(m); setTimeout(() => setMsg(''), 3000); };

  const handleStatus = async (id, status) => {
    try { await updateMeetingStatus(id, status); flash(`✅ Meeting marked as ${status}`); load(); }
    catch (e) { flash('❌ Failed'); }
  };

  const today = new Date().toDateString();
  const todayMeetings = meetings.filter(m => new Date(m.date).toDateString() === today);
  const upcoming = meetings.filter(m => m.status === 'scheduled' && new Date(m.date) >= new Date());
  const completed = meetings.filter(m => m.status === 'completed');

  if (loading) return (
    <div className="flex-center" style={{ height: '80vh', flexDirection: 'column', gap: '1rem' }}>
       <div className="spinner"></div>
       <p style={{ color: '#64748b', fontWeight: 500 }}>Fetching your schedule...</p>
    </div>
  );

  return (
    <div className="dashboard-container" style={{ padding: '2rem', maxWidth: '1200px', margin: '0 auto' }}>

      {/* Header Section */}
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: '2.5rem' }}>
        <div>
          <h1 style={{ fontSize: '1.875rem', fontWeight: 700, color: '#1e293b', margin: 0 }}>HOD Dashboard</h1>
          <p style={{ color: '#64748b', marginTop: '0.25rem' }}>Welcome back, {user.name}</p>
        </div>
        <Link to="/hod/schedule">
          <button className="btn-primary-new">+ New Availability</button>
        </Link>
      </header>

      {/* Flash Messages */}
      {msg && (
        <div className={`alert-toast ${msg.includes('❌') ? 'error' : 'success'}`}>
          {msg}
        </div>
      )}

      {/* Stats Grid */}
      <div className="stats-grid-new">
        <div className="stat-item">
          <span className="stat-icon">📅</span>
          <div>
            <p className="stat-label-new">Today</p>
            <h3 className="stat-val">{todayMeetings.length}</h3>
          </div>
        </div>
        <div className="stat-item">
          <span className="stat-icon" style={{ background: '#e0f2fe' }}>⏳</span>
          <div>
            <p className="stat-label-new">Upcoming</p>
            <h3 className="stat-val blue-text">{upcoming.length}</h3>
          </div>
        </div>
        <div className="stat-item">
          <span className="stat-icon" style={{ background: '#f0fdf4' }}>✅</span>
          <div>
            <p className="stat-label-new">Completed</p>
            <h3 className="stat-val green-text">{completed.length}</h3>
          </div>
        </div>
      </div>

      {/* Meetings Section */}
      <div className="main-card">
        <h2 style={{ fontSize: '1.25rem', marginBottom: '1.5rem', color: '#334155' }}>Schedule Overview</h2>

        {meetings.length === 0 ? (
          <div className="empty-state">
            <div style={{ fontSize: '3rem' }}>📁</div>
            <p>No meetings found in your calendar.</p>
          </div>
        ) : (
          <div className="meeting-list">
            {meetings.map(m => (
              <div key={m._id} className={`meeting-row ${m.status}`}>
                <div className="meeting-info">
                  <div className="user-avatar">
                    {(m.scheduledBy?.name || 'U').charAt(0).toUpperCase()}
                  </div>
                  <div>
                    <h4 className="agenda-text">{m.agenda || m.title}</h4>
                    <p className="attendee-text">
                      {m.scheduledBy?.name === user.name 
                        ? `With: ${m.attendees?.map(a => a.user?.name).join(', ') || '—'}` 
                        : `By: ${m.scheduledBy?.name}`}
                    </p>
                  </div>
                </div>

                <div className="meeting-time">
                  <span className="date-tag">{new Date(m.date).toLocaleDateString('en-IN', { day: '2-digit', month: 'short' })}</span>
                  <span className="time-tag">{m.time}</span>
                </div>

                <div className="meeting-status">
                  <span className={`status-pill ${m.status}`}>{m.status}</span>
                </div>

                <div className="meeting-actions">
                  {m.status === 'scheduled' && m.scheduledBy?._id === user.id && (
                    <button className="action-btn check" onClick={() => handleStatus(m._id, 'completed')}>Done</button>
                  )}
                  {m.status === 'completed' && <span className="done-text">✓ Completed</span>}
                  {m.meetingLink && m.status === 'scheduled' && (
                    <a href={m.meetingLink} target="_blank" rel="noreferrer">
                      <button className="action-btn join">Join</button>
                    </a>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

export default HodDashboard;
